def light_switch_group(n, events):
    state = [False] * n
    resets = 0
    flips = 0
    resets_pending = 0
    last_toggled = -1
    for event in events:
        if event[0] == "toggle":
            if resets_pending:
                resets_pending -= 1
            else:
                flips += 1
                if flips % 2 == 1:
                    state[event[1]] = not state[event[1]]
                last_toggled = event[1]
        elif event[0] == "toggle_all":
            if resets_pending:
                resets_pending -= 1
            else:
                flips += 2 * n
                flips %= 2 * n
                state[event[1]] = not state[event[1]]
                flips -= 2
                flips %= 2 * n
                if flips % 2 == 1:
                    state[last_toggled] = not state[last_toggled]
        elif event[0] == "reset":
            resets += 1
            flips -= 2 * n
    if resets % 2 == 1:
        return [False] * n
    while flips > 0:
        if flips % 2 == 1:
            state[flips // 4] = not state[flips // 4]
        flips -= 1
        flips %= 2 * n
    return state
