def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    stops = []

    if direction == 1:
        # Up sweep: start_floor, start_floor + 1, ..., top_floor
        for floor in range(start_floor, top_floor + 1):
            if floor in requests:
                stops.append(floor)
    else:
        # Down sweep: start_floor, start_floor - 1, ..., 1
        for floor in range(start_floor, 0, -1):
            if floor in requests:
                stops.append(floor)
    return stops
```

