def queue_with_capacity_serve(events, capacity):
    from collections import deque
    queue = deque()
    for event in events:
        if event[0] == "arrive":
            queue.append(event[1])
        else:
            taken = min(capacity, len(queue))
            for _ in range(taken):
                queue.popleft()
    return list(queue)
```

